sh("wsl: a plain node test path that climbs",
   "wsl -e node ../x.test.mjs", "deny", rule=WSL_RULE, cwd=NOGIT)
sh("wsl: a plain node test path that is absolute",
   "wsl -e node /tmp/evil.test.mjs", "deny", rule=WSL_RULE, cwd=NOGIT)

