for _tool, _path in (("Edit", "docs/x.md"), ("Write", "decisions/y.md"), ("Edit", "README.MD")):
    add("record-writer: %s of %s is allowed" % (_tool, _path), "allow", tool=_tool,
        file_path=_path, new_string="x", **RW)
